function Assert-HCM5VS1NoEngineProcess {
 $processes=@(Get-CimInstance Win32_Process -Filter "Name='UnrealEditor.exe' OR Name='UnrealEditor-Cmd.exe' OR Name='HarborCity.exe' OR Name='HarborCity-Win64-Shipping.exe'")
 if($processes.Count){throw ('Exit the existing engine/game normally before this operation. PIDs: '+(($processes | ForEach-Object ProcessId) -join ', '))}
}
